B.aiI=new A.bP("\ud83d\udc67","Ayaan waxay la tagtay hooyadeed suuqa si ay u iibsadaan khudaar cusub.","Ayaan went to the market with her mother to buy fresh vegetables.","\u0630\u0647\u0628\u062a \u0639\u064a\u0627\u0646 \u0645\u0639 \u0623\u0645\u0647\u0627 \u0625\u0644\u0649 \u0627\u0644\u0633\u0648\u0642 \u0644\u0634\u0631\u0627\u0621 \u062e\u0636\u0631\u0648\u0627\u062a \u0637\u0627\u0632\u062c\u0629.")
B.aiW=new A.bP("\ud83e\udd55",'"Salaan!" ayay tidhi ganacsatada. "Ma haysaa karooto?"','"Hello!" she said to the seller. "Do you have carrots?"','"\u0645\u0631\u062d\u0628\u0627\u064b!" \u0642\u0627\u0644\u062a \u0644\u0644\u0628\u0627\u0626\u0639. "\u0647\u0644 \u0639\u0646\u062f\u0643 \u062c\u0632\u0631\u061f"')
